pub fn edit(a: Str, b: Str) -> Int {
  let xs = a.codes()
  let ys = b.codes()
  let m = ys.len()
  var prev: List[Int] = []
  for j in range(0, m + 1) {
    prev = prev.push(j)
  }
  for i in range(1, xs.len() + 1) {
    var row: List[Int] = [i]
    for j in range(1, m + 1) {
      var cost = 1
      if xs.get_or(i - 1, 0) == ys.get_or(j - 1, 0) {
        cost = 0
      }
      let up = prev.get_or(j, 0) + 1
      let left = row.get_or(j - 1, 0) + 1
      let diag = prev.get_or(j - 1, 0) + cost
      row = row.push(up.min(left).min(diag))
    }
    prev = row
  }
  return prev.get_or(m, 0)
}
